import java.math.BigDecimal;
import java.math.RoundingMode;

public final class FeeCalculator {

    private static final BigDecimal DELIVERY_FREE_THRESHOLD = new BigDecimal("200");
    private static final BigDecimal DELIVERY_FEE = new BigDecimal("12");

    private static final BigDecimal SERVICE_ZERO = BigDecimal.ZERO;
    private static final BigDecimal SERVICE_LOW_FEE = new BigDecimal("2");
    private static final BigDecimal SERVICE_HIGH_FEE = new BigDecimal("5");
    private static final BigDecimal SERVICE_LOW_MAX = new BigDecimal("100");

    private FeeCalculator() {
    }

    /**
     * 配送费：
     * - itemCount == 0：返回 0
     * - itemCount > 0 且 amount > 200：返回 0
     * - 其他合法情况：返回 12
     *
     * 金额单位：元
     * 返回值保留 2 位小数，不修改输入 BigDecimal。
     */
    public static BigDecimal deliveryFee(BigDecimal amount, int itemCount) {
        validateAmount(amount);
        validateItemCount(itemCount);

        if (itemCount == 0) {
            return scale2(BigDecimal.ZERO);
        }

        if (amount.compareTo(DELIVERY_FREE_THRESHOLD) > 0) {
            return scale2(BigDecimal.ZERO);
        }

        return scale2(DELIVERY_FEE);
    }

    /**
     * 服务费：
     * - amount == 0：返回 0
     * - 0 < amount <= 100：返回 2
     * - amount > 100：返回 5
     *
     * 金额单位：元
     * 返回值保留 2 位小数，不修改输入 BigDecimal。
     */
    public static BigDecimal serviceFee(BigDecimal amount) {
        validateAmount(amount);

        if (amount.compareTo(BigDecimal.ZERO) == 0) {
            return scale2(SERVICE_ZERO);
        }

        if (amount.compareTo(SERVICE_LOW_MAX) <= 0) {
            return scale2(SERVICE_LOW_FEE);
        }

        return scale2(SERVICE_HIGH_FEE);
    }

    private static void validateAmount(BigDecimal amount) {
        if (amount == null) {
            throw new IllegalArgumentException("amount must not be null");
        }
        if (amount.compareTo(BigDecimal.ZERO) < 0) {
            throw new IllegalArgumentException("amount must be greater than or equal to 0");
        }
    }

    private static void validateItemCount(int itemCount) {
        if (itemCount < 0) {
            throw new IllegalArgumentException("itemCount must be greater than or equal to 0");
        }
    }

    private static BigDecimal scale2(BigDecimal value) {
        return value.setScale(2, RoundingMode.UNNECESSARY);
    }
}
```

