        assertEquals("service amount=99.99", "2.00",
                FeeCalculator.serviceFee(new BigDecimal("99.99")));

        assertEquals("service amount=100", "2.00",
                FeeCalculator.serviceFee(new BigDecimal("100")));

        assertEquals("service amount=100.01", "5.00",
                FeeCalculator.serviceFee(new BigDecimal("100.01")));

        assertEquals("service amount=200", "5.00",
                FeeCalculator.serviceFee(new BigDecimal("200")));

        BigDecimal original = new BigDecimal("100.01");
        FeeCalculator.serviceFee(original);
        assertEquals("service must not modify input", "100.01", original.toPlainString());
    }

    private static void testInvalidInputs() {
        assertThrows("delivery null amount", IllegalArgumentException.class,
                () -> FeeCalculator.deliveryFee(null, 1));

        assertThrows("delivery negative amount", IllegalArgumentException.class,
                () -> FeeCalculator.deliveryFee(new BigDecimal("-0.01"), 1));

        assertThrows("delivery negative itemCount", IllegalArgumentException.class,
                () -> FeeCalculator.deliveryFee(new BigDecimal("10"), -1));

        assertThrows("service null amount", IllegalArgumentException.class,
                () -> FeeCalculator.serviceFee(null));

        assertThrows("service negative amount", IllegalArgumentException.class,
                () -> FeeCalculator.serviceFee(new BigDecimal("-0.01")));
    }

    private static void assertEquals(String name, String expected, String actual) {
        if (!expected.equals(actual)) {
            throw new AssertionError(name + " expected=" + expected + " actual=" + actual);
        }
    }

    private static void assertThrows(String name, Class<? extends Throwable> expectedType, Runnable action) {
        try {
            action.run();
        } catch (Throwable t) {
            if (expectedType.isInstance(t)) {
                return;
            }
            throw new AssertionError(name + " expected " + expectedType.getName()
                    + " but got " + t.getClass().getName(), t);
        }
        throw new AssertionError(name + " expected " + expectedType.getName() + " but nothing was thrown");
    }
