        validateAmount(amount);

        if (amount.compareTo(BigDecimal.ZERO) == 0) {
            return scaleMoney(SERVICE_FEE_ZERO);
        }

        if (amount.compareTo(SERVICE_LOW_MAX) <= 0) {
            return scaleMoney(SERVICE_FEE_LOW);
        }

        return scaleMoney(SERVICE_FEE_HIGH);
